  "total": 9260,
  "articles": [
    {
      "title": "Міста Полтавської області",
      "snippet": "Лубни Миргород Пирятин Полтава Решетилівка Хорол До складу Полтавської області входять 16 міст. Найбільшим за населенням є Полтава з населенням у 310 755",
      "words": 219
    },
    {
      "title": "Адміністративно-територіальний устрій Полтавської області",
      "snippet": "устрій Полтавської області — поділ Полтавської області задля доцільнішого використання людських і природних ресурсів. Від 17 липня 2020 року Полтавська область",
      "words": 3194
    },
    {
      "title": "Полтавська область",
      "snippet": "Азовського. Докладніше: Рослинність Полтавської області та Тваринний світ Полтавської області Флора Полтавської області нараховує близько 2 тисяч видів різних",
      "words": 5076
    },
    {
      "title": "Карлівка",
      "snippet": "Ка́рлівка — місто в Україні, у Карлівській міській громаді Полтавського району Полтавської області. До 2020 року було центром Карлівського району. Площа —",
      "words": 3846
    },
    {
      "title": "Горішні Плавні",
      "snippet": "та культурне місто Полтавської області. Офіційна дата заснування — 29 листопада 1960 року. 24 квітня 1972 року селище набуло статусу міста, а 6 квітня",
      "words": 8947
    },
    {
      "title": "Населення Полтавської області",
      "snippet": "Населення Полтавської області — частина населення України, що проживає на території Полтавської області. Станом на 1 листопада 2014 року становило 1 450 468",
      "words": 4976
    },
    {
      "title": "Водосховища Полтавської області",
      "snippet": "Водосховища Полтавської області — водосховища, які розташовані на території Полтавської області (в адміністративних районах і басейнах річок) — без «транзитних»",
      "words": 343
    },
    {
      "title": "Герб Полтавської області",
      "snippet": "(1878-1918) Прапор Полтавської області Герб Полтавського району Символіка Полтавської області Гречило А. Сучасні символи областей України. — К., Львів",
      "words": 320
    },
    {
      "title": "Історія Полтавської області",
      "snippet": "які передували Полтавській області: Полтавський полк, Полтавська губернія, Полтавська округа період власне історії Полтавської області. Полтавщина була",
      "words": 12051
    },
    {
      "title": "Адміністративний устрій Семенівського району Полтавської області",
      "snippet": "району — адміністративно-територіальний поділ Семенівського району Полтавської області на 1 селищну громаду, 1 сільську громаду і 13 сільських рад, які",
      "words": 75
    }
  ]
}

